#ifndef INTEGRATION_CONTRACT_H
#define INTEGRATION_CONTRACT_H

#include <atomic>
#include <cstdint>
#include <cstddef>

// Forward declaration of the lock-free ring buffer (we assume a type like moodycamel::ReaderWriterQueue)
// For the purpose of this contract, we define the interface we expect.
// In practice, we would include the actual header or use a forward declaration and then define the buffer as a member.
template<typename T> class SPSCRingBuffer;

// Shared constants (these would be defined in config.h generated by the ML export tool)
// For the contract, we assume they are available via some config header.
// We'll define them here for completeness, but note: in reality, they come from config.h.
#ifndef MAX_BATCH
#define MAX_BATCH 32
#endif
#ifndef MAX_D_STATE
#define MAX_D_STATE 64
#endif
#ifndef MAX_D_MODEL
#define MAX_D_MODEL 64
#endif
#ifndef MAX_PARAM_ATOMS
#define MAX_PARAM_ATOMS 256
#endif

// Shared Schemas

// AudioConfig: set by the host during activation, read-only after that.
struct AudioConfig {
    uint32_t sampleRate;    // e.g., 44100, 48000
    uint32_t maxBlockSize;  // maximum block size the host will use
    uint16_t numChannels;   // number of audio channels (e.g., 1 for mono, 2 for stereo)
};

// ConditioningFrame: updated by the ARA thread, read by the audio thread.
// Uses a seqlock (sequence lock) for safe concurrent access.
struct ConditioningFrame {
    float tempoBPM;                 // Beats per minute
    float keySig;                   // Key signature (e.g., 0.0 for C, 0.5 for F#, etc. - we can define a mapping)
    float chordOneHot[12];          // One-hot encoding of the chord (12 semitones)
    uint64_t seqLock;               // Seqlock: even when writer is not writing, odd when writing.
};

// MambaState: the state of the SSM model.
// Note: We align to 64-byte cache lines to avoid false sharing and to allow aligned loads.
struct MambaState {
    // We use a 3D array: [batch][d_state][d_model]
    // However, note: the Mamba state is typically 2D: [d_state, d_model] for each layer and batch?
    // We'll assume the state is per layer and we have multiple batches (for parallelism) but in audio we usually have batch=1.
    // To keep it general, we support a batch dimension.
    alignas(64) float h[MAX_BATCH][MAX_D_STATE][MAX_D_MODEL];
    // We might have more state (e.g., for the convolution) but we keep it simple for the contract.
    // Additional state can be added here, but must be within the bounds and aligned.
};

// ParamAtom: a single parameter update to be sent from the main thread to the audio thread.
// We use an SPSC ring buffer to send these atoms.
struct ParamAtom {
    uint32_t id;          // Parameter ID (must be less than the total number of parameters)
    float value;          // Parameter value (normalized 0.0 to 1.0, or as defined by the plugin)
    uint64_t frameOffset; // The audio frame at which this parameter change should take effect.
                          // This allows for sample-accurate automation.
};

// Communication Protocols (as functions or macros that define the expected behavior)

// Audio -> Main (state save): Double-buffer MambaState.
// We assume the audio thread has two buffers: stateBuffers[2].
// The audio thread writes to the current buffer, then flips the atomic index.
// The main thread reads from the buffer that is not being written to.
// We use an atomic index (0 or 1) to indicate which buffer is currently being written by the audio thread.
// The main thread must read the index, then read the other buffer (1 - index) to get a consistent snapshot.
// However, note: the audio thread might be writing to buffer A, then flips to buffer B. The main thread must
// ensure it reads the buffer that is not being written. We can do:
//
//   uint32_t writeIndex = atomic_load(&stateWriteIndex); // which buffer is the audio thread writing to?
//   uint32_t readIndex = 1 - writeIndex;
//   const MambaState& state = stateBuffers[readIndex];
//
// But note: the audio thread might flip the index after we read it but before we read the buffer.
// To avoid that, we can use a double-buffering technique with a seqlock on the state itself, or we can
// use the fact that the audio thread only writes to one buffer at a time and we read the other.
// However, if we read the index and then the audio thread flips, we might read the buffer that is being
// written in the next cycle. But that is acceptable because we are only reading for non-realtime purposes
// (e.g., saving state) and we can tolerate a little staleness or we can retry.
//
// Alternatively, we can use a seqlock for the entire MambaState. However, the state is large and we
// want to avoid blocking the audio thread. The double-buffer with an index is wait-free for the readers
// (main thread) if we guarantee that the audio thread only writes to one buffer and then flips, and the
// main thread always reads the other buffer. The audio thread must not write to the buffer that the main
// thread is reading. We can achieve this by having the audio thread:
//   1. Write to buffer A.
//   2. Flush the write buffer (to make sure the write is visible).
//   3. Flip the index to point to buffer B (so that the main thread now knows to read buffer A).
//   4. Then write to buffer B.
//
// The main thread:
//   - Reads the index (which buffer the audio thread is currently writing to).
//   - Reads the other buffer (1 - index).
//
// This is safe because the audio thread is always writing to the buffer indicated by the index, and the
// main thread reads the opposite. The audio thread must not start writing to the other buffer until after
// it has flipped the index and the main thread has read the old value? Actually, the main thread reads
// the index and then the buffer. There is a small window where the audio thread flips the index and then
// starts writing to the new buffer, but the main thread has already read the index and is reading the old
// buffer (which is now not being written to). So it's safe.
//
// We'll define the contract for the double-buffer as follows:

// We assume the following are defined in the implementation (not in this header, but the contract is):
//   extern MambaState stateBuffers[2];
//   extern std::atomic<uint32_t> stateWriteIndex; // which buffer the audio thread is currently writing to (0 or 1)
//
// The audio thread:
//   - Writes to stateBuffers[stateWriteIndex.load()]\n
//   - After writing, it may flip the index for the next write (but note: we flip before writing to the next buffer?)\n
//   Actually, we want the main thread to read the buffer that is not being written. So the audio thread should:
//   - Write to buffer A.
//   - Then flip the index to B (so that the main thread knows that A is safe to read).
//   - Then write to buffer B.
//   - Then flip the index to A, and so on.
//
// However, note: the audio thread might write multiple times to the same buffer before flipping? We want to
// flip after each write (or after a set of writes) so that the main thread can read a relatively recent state.
//
// We'll leave the exact flipping policy to the implementation, but the contract for the main thread is:
//   - To get a consistent snapshot of the state, read the index, then read the buffer at (1 - index).

// Main -> Audio (params): SPSC ring buffer of ParamAtom.
// We assume a ring buffer with a fixed size (MAX_PARAM_ATOMS) that is lock-free and wait-free for the
// producer (main thread) and consumer (audio thread) under the condition that the buffer does not full
// (or we drop old events if full). We'll assume the buffer is never full in practice, or we define a
// policy (e.g., overwrite old). For the contract, we define the operations:
//
//   // Main thread (producer):
//   bool pushParam(const ParamAtom& atom);
//   // Audio thread (consumer):
//   bool popParam(ParamAtom& atom);
//
// We assume the ring buffer is implemented such that these operations are lock-free.

// ARA -> Audio (conditioning): Writer (ARA thread) writes ConditioningFrame, increments seqlock.
// The seqlock protocol:
//   - Writer:
//       1. Increment seqLock to make it odd (start writing).
//       2. Write the ConditioningFrame (tempoBPM, keySig, chordOneHot).
//       3. Increment seqLock to make it even (done writing).
//   - Reader (audio thread):
//       do {
//           uint64_t start = frame.seqLock;
//           if (start & 1) // odd, retry
//               continue;
//           // Read the data
//           float tempo = frame.tempoBPM;
//           float key = frame.keySig;
//           float chord[12];
//           memcpy(chord, frame.chordOneHot, sizeof(chord));
//           uint64_t end = frame.seqLock;
//       } while (start != end);
//   This ensures that if the writer updated the frame during the read, we retry.

// Memory Layout (as comments in the header, since we cannot enforce it here)
// - Weights: read-only, mmap'd, starting at page boundary (we assume the implementation uses mmap and
//   sets the memory to read-only).
// - Working buffers: allocated by MambaProcessor::prepare(AudioConfig), owned by audio thread.
// - UI buffers: separate heap, main thread only.

// Constraints (as comments)
// - All atomics use std::memory_order_acquire/release minimum; seqlock uses acquire/release.
// - No std::shared_ptr, std::string, or dynamic containers cross thread boundaries.
// - All arrays bounded by MAX_* constants from generated config.h.

// We do not define any classes or functions in this header because it is a contract.
// The actual implementation will fulfill this contract.

#endif // INTEGRATION_CONTRACT_H